// The LLM Assistant node: hand Claude BOTH reference images plus the
// prompt-generator spec, exactly like the Higgsfield graph.
const spec = [
  'You are an image prompt generator. Two references are attached: image 1 defines the style and body build of the character, image 2 defines the head shape and eyes. Output ONE new English prompt that generates the same character in a different look.',
  '',
  'LOCKED CORE (carried into every prompt):',
  '- Head: two intersecting circles forming a figure-eight / infinity silhouette, very light lavender-white #E8EAFB, head large relative to body',
  '- Eyes: two black slanted parallelogram shapes with rounded corners, one inside each lobe of the head, tilted to the right, color #0B0B1E, exactly as in image 2, BOTH LOOKING TO THE LEFT',
  '- The eyes are completely flat solid black: no highlights, no glints, no catchlights, no white or light shapes inside the eyes',
  '- No mouth, nose, ears, eyebrows, hair',
  '- Style: flat vector cartoon, retro mascot, thick uniform black outline, no gradients, no shadows, no textures',
  '- Hands: white four-fingered cartoon gloves',
  '- Body small relative to head, mascot proportions',
  '- Background: one flat solid color stated as a hex value, no details, no patterns, no gradients, no vignette',
  '- Framing: full body, centered, square 1:1',
  '- No text, logos, captions, watermarks',
  '- NEVER include weapons of any kind, brand names, or real people',
  '',
  'WHAT CHANGES EVERY RUN - before picking, generate a number from 1 to 999 and use it as a seed so sets never repeat. Pick one item from each category (you may invent options outside the lists):',
  '1. Outfit: business suit, spacesuit, chef jacket, kimono, biker leather jacket, surgical scrubs, mechanic overalls, pilot uniform, cowboy outfit, wetsuit, knight armor, tracksuit, lab coat, mail carrier uniform, boxing shorts and robe, wizard robe, firefighter gear, football kit, toga, winter parka',
  '2. Pose: waving, arms crossed, hands on hips, pointing forward, thumbs up, saluting, shrugging, walking sideways, crouching, leaning, both arms up, holding an object in front, standing at attention, scratching the back of the head, jumping',
  '3. Prop (sometimes none): briefcase, coffee mug, skateboard, umbrella, guitar, fishing rod, laptop, food tray, fire extinguisher, microphone, rolling suitcase, butterfly net, book, key on a chain, balloon, broom, racket',
  '4. Head accessory (sits ON TOP of the figure-eight, never covers the eyes): none, cap, headphones, hard hat, astronaut helmet, bandana, crown, chef hat, ushanka, top hat, headband with antennae, forehead wrap',
  '5. Footwear: black rounded boots, sneakers, tall boots, sandals, ice skates, bare glove-style feet',
  '6. Background color: one flat tone as hex, contrasting the near-white head, not repeating the outfit colour',
  '',
  'OUTPUT FORMAT: return only the prompt text, one paragraph, 90-150 words, starting with "Seed: <n>." No headings, comments, numbering, quotes or explanations. Spell out the head shape, eye shape, palette and background explicitly.',
].join('\n');

const character = await this.helpers.getBinaryDataBuffer(0, 'character');
const eyes = await this.helpers.getBinaryDataBuffer(0, 'eyes');

const claudeBody = {
  model: 'claude-sonnet-5',
  max_tokens: 1024,
  messages: [
    {
      role: 'user',
      content: [
        { type: 'image', source: { type: 'base64', media_type: 'image/png', data: character.toString('base64') } },
        { type: 'image', source: { type: 'base64', media_type: 'image/png', data: eyes.toString('base64') } },
        { type: 'text', text: spec },
      ],
    },
  ],
};

return [{ json: { claudeBody }, binary: $input.all()[0].binary }];

// Pull the prompt out of Claude's response, derive the output filenames.
const resp = $input.all()[0].json;
const prompt = (resp.content || [])
  .filter((c) => c.type === 'text')
  .map((c) => c.text)
  .join(' ')
  .trim();
if (!prompt) throw new Error('Claude returned no prompt text: ' + JSON.stringify(resp).slice(0, 300));

const seed = (prompt.match(/Seed:\s*(\d+)/i) || [])[1] || 'x';
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const base = `mofo-s${seed}-${stamp}`;

return [{
  json: { prompt, seed, fileName: base + '.png', promptFile: base + '.txt' },
  binary: $input.all()[0].binary,
}];
